<?php
declare(strict_types=1);
namespace CB\Dictionary\Integration\Builders\Bricks;
use CB\Dictionary\Content\Taxonomies;
use CB\Dictionary\Frontend\Conditions as FrontendConditions;
defined( 'ABSPATH' ) || exit;
final class Conditions { private const GROUP='cb_dictionary'; public static function init():void{add_filter('bricks/conditions/groups',[self::class,'groups']);add_filter('bricks/conditions/options',[self::class,'options']);add_filter('bricks/conditions/result',[self::class,'result'],10,3);} public static function groups(array $g):array{$g[self::GROUP]=['name'=>__('Core Blueprint Dictionary','core-blueprint-dictionary')];return $g;} public static function options(array $o):array{$o['cb_dictionary_is_entry']=['group'=>self::GROUP,'name'=>__('Context is a Dictionary entry','core-blueprint-dictionary'),'type'=>'select','options'=>self::bools()];$o['cb_dictionary_is_featured']=['group'=>self::GROUP,'name'=>__('Dictionary entry is featured','core-blueprint-dictionary'),'type'=>'select','options'=>self::bools()];$o['cb_dictionary_category']=['group'=>self::GROUP,'name'=>__('Dictionary category slug','core-blueprint-dictionary'),'type'=>'text'];$o['cb_dictionary_tag']=['group'=>self::GROUP,'name'=>__('Dictionary tag slug','core-blueprint-dictionary'),'type'=>'text'];$o['cb_dictionary_letter']=['group'=>self::GROUP,'name'=>__('Dictionary letter slug','core-blueprint-dictionary'),'type'=>'text'];return $o;} public static function result(bool $result,string $key,array $c):bool{if(!str_starts_with($key,'cb_dictionary_')){return $result;}$id=Context::entry_id();$expected='0'!==(string)($c['value']??'1');$actual=match($key){'cb_dictionary_is_entry'=>FrontendConditions::is_entry($id),'cb_dictionary_is_featured'=>FrontendConditions::is_featured($id),'cb_dictionary_category'=>FrontendConditions::has_term($id,Taxonomies::CATEGORY,(string)($c['value']??'')),'cb_dictionary_tag'=>FrontendConditions::has_term($id,Taxonomies::TAG,(string)($c['value']??'')),'cb_dictionary_letter'=>FrontendConditions::has_term($id,Taxonomies::LETTER,(string)($c['value']??'')),default=>false,};return in_array($key,['cb_dictionary_category','cb_dictionary_tag','cb_dictionary_letter'],true)?$actual:($actual===$expected);} private static function bools():array{return ['1'=>__('Yes','core-blueprint-dictionary'),'0'=>__('No','core-blueprint-dictionary')];} }
